import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(JUnit4.class)
public class TextNodeTest {

    @Test
    public void newNodeTextNoWhitespaceTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void newNodeTextWithWhitespaceTest() {
        String text = "   Hello   World  ";
        TextNode node = new TextNode(text);
        assertEquals("   Hello   World  ", node.text());
    }

    @Test
    public void newNodeTextBlankTest() {
        String text = "";
        TextNode node = new TextNode(text);
        assertTrue(node.isBlank());
    }

    @Test
    public void textMethodIsNotSameAsNewNodeTextMethodTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertNotEquals(node.text(), node.nodeName());
    }

    @Test
    public void splitTextZeroOffsetTest() {
        TextNode node = new TextNode("Hello World");
        TextNode newNode = node.splitText(0);
        assertNotNull(newNode);
        assertEquals("Hello World", newNode.text());
    }

    @Test
    public void cloneMethodReturnsNewTextNodeWithSameTextTest() {
        String text = "Hello World";
        TextNode originalNode = new TextNode(text);
        TextNode clonedNode = originalNode.clone();
        assertNotNull(clonedNode);
        assertEquals(text, clonedNode.text());
    }

    @Test
    public void createFromEncodedStringTest() {
        String encodedText = "%3CHello%20World%3E";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertNotNull(node);
        assertEquals("Hello World", node.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "   Hello   World  ";
        String expected = "Hello World";
        assertEquals(expected, StringUtil.normaliseWhitespace(text));
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "   Hello   World  ";
        String expected = "Hello World";
        assertEquals(expected, StringUtil.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder sb = new StringBuilder("   ");
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        assertFalse(TextNode.lastCharIsWhitespace(new StringBuilder()));
    }
}
